    {
      "subject": {
        "value": "...",
        "evidence": [
          {"segment": "title|text", "quote": "...", "occurrence": 1}
        ]
      },
      "predicate": {
        "value": "...",
        "evidence": [
          {"segment": "title|text", "quote": "...", "occurrence": 1}
